import {transformTrackedSequence} from './model.js';
import {createAnimationTrack,compileAnimationTracks,sampleAnimationTracks} from './animation-tracks.js';
export function installAnimationTracks({getProject,getSelection,mutate,redraw,actor,editor}){
 const panel=document.createElement('details');panel.id='animation-tracks';panel.innerHTML='<summary>Independent animation tracks</summary><p>Box-select a region, then make a track. Source pixels stay intact. Right-click removes mask cells; left-drag adds. Paw/support markers remain with the contact driver.</p><label>Track name <input data-track="name" value="Tail" maxlength="80"></label><label><input type="checkbox" data-track="gaze"> This track owns gaze</label><button data-track="create">Make track from selection</button><label>Selected track <select data-track="select"></select></label><label><input type="checkbox" data-track="edit"> Edit mask on canvas</label><label>Source frames (1-based, e.g. 4-11)<input data-track="frames"></label><label>Independent holds (ms, comma-separated; blank uses source)<input data-track="holds"></label><label>Minimum rate <input data-track="min" type="number" min="0.5" max="2" step="0.05" value="0.85"></label><label>Maximum rate <input data-track="max" type="number" min="0.5" max="2" step="0.05" value="1.15"></label><button data-track="save">Apply track settings</button><button data-track="remove">Remove track metadata</button><button data-track="mirror">Mirror whole sequence with tracks</button><label><input data-track="solo" type="checkbox"> Solo selected track in preview</label><label><input data-track="mute" type="checkbox"> Mute selected track in preview</label><label>Preview seed <input data-track="seed" type="number" value="1"></label><output data-track="status" role="status"></output>';
 const fields=document.createElement('div');fields.className='animation-track-fields';while(panel.children.length>1)fields.append(panel.children[1]);panel.append(fields);
 const $=key=>panel.querySelector('[data-track="'+key+'"]');let selectedId='',compiled=null,projectKey=null,started=performance.now(),paint=null;
 const selected=()=>getProject()?.animationTracks?.tracks.find(t=>t.id===selectedId),driver=()=>getProject()?.animationTracks?.driver;
 function members(text,p){const indices=[];for(const term of text.split(',').map(s=>s.trim()).filter(Boolean)){const pair=term.split('-').map(Number),lo=pair[0],hi=pair[1]??lo;if(!Number.isInteger(lo)||!Number.isInteger(hi)||lo<1||hi<lo||hi>p.frames.length)throw Error('Choose a valid source frame range.');for(let i=lo;i<=hi;i++)indices.push(i-1);}return [...new Set(indices)].map(i=>p.frames[i].id);}
 function change(fn){compiled=null;const result=mutate(fn);redraw();return result;}
 $('create').onclick=()=>change(()=>{const p=getProject(),box=getSelection();if(!box)throw Error('Use Select / move to box a region first.');const mask=[];for(let y=box.y;y<box.y+box.height;y++)for(let x=box.x;x<box.x+box.width;x++)mask.push(y*24+x);const frameIds=p.frames.filter(f=>(f.role||'cycle')==='cycle').map(f=>f.id);const t=createAnimationTrack(p,{name:$('name').value,mask,frameIds,actor:actor(),gazeOwner:$('gaze').checked});selectedId=t.id;});
 $('select').onchange=()=>{selectedId=$('select').value;render();redraw();};
 $('save').onclick=()=>change(()=>{const p=getProject(),t=selected();if(!t)return;if(p.frames.some(f=>f.locked&&(t.id===driver()||t.frameIds?.includes(f.id))))throw Error('Unlock the track source frames before changing playback.');t.name=$('name').value;if(t.id!==driver()){t.frameIds=members($('frames').value,p);t.rateMin=Number($('min').value);t.rateMax=Number($('max').value);const text=$('holds').value.trim();if(text)t.holds=text.split(',').map(Number);else delete t.holds;}if($('gaze').checked)p.animationTracks.gazeOwner=t.id;else if(p.animationTracks.gazeOwner===t.id)p.animationTracks.gazeOwner=p.animationTracks.driver;});
 $('mirror').onclick=()=>change(()=>transformTrackedSequence(getProject(),'flip-x',actor()));
 $('remove').onclick=()=>change(()=>{const p=getProject(),t=selected();if(!t)return;if(p.frames.some(f=>f.locked&&(t.id===driver()||t.frameIds?.includes(f.id))))throw Error('Unlock the track source frames before removing playback metadata.');if(t.id===driver())delete p.animationTracks;else{p.animationTracks.tracks=p.animationTracks.tracks.filter(x=>x!==t);if(p.animationTracks.gazeOwner===t.id)delete p.animationTracks.gazeOwner;}selectedId='';$('edit').checked=false;});
 for(const key of ['solo','mute','seed','edit'])$(key).onchange=()=>{redraw();};
 function render(){const p=getProject();if(!p)return;if(projectKey!==p.projectId){projectKey=p.projectId;started=performance.now();$('edit').checked=false;selectedId='';}compiled=compileAnimationTracks(p);const tracks=p.animationTracks?.tracks||[];if(!tracks.some(t=>t.id===selectedId))selectedId=tracks.at(-1)?.id||'';$('select').replaceChildren(...tracks.map(t=>new Option(t.name+(t.id===driver()?' · contact driver':''),t.id)));$('select').value=selectedId;const t=selected(),independent=t&&t.id!==driver();for(const key of ['edit','frames','holds','min','max'])$(key).disabled=!independent;for(const key of ['save','remove','solo','mute'])$(key).disabled=!t;
  if(t){$('name').value=t.name;$('frames').value=(t.frameIds||[]).map(id=>p.frames.findIndex(f=>f.id===id)+1).join(',');$('holds').value=t.holds?.join(',')||'';$('min').value=t.rateMin??1;$('max').value=t.rateMax??1;$('gaze').checked=(p.animationTracks.gazeOwner||driver())===t.id;}$('status').textContent=tracks.length?tracks.length+' tracks · '+(t?.mask?.length||0)+' mask cells · original frames retained':'No independent tracks. Flat playback remains available.';
 }
 function point(e){const r=editor.getBoundingClientRect();return{x:Math.max(0,Math.min(23,Math.floor((e.clientX-r.left)/r.width*24))),y:Math.max(0,Math.min(23,Math.floor((e.clientY-r.top)/r.height*24)))};}
 function paintTo(p){const from=paint.last,n=Math.max(Math.abs(p.x-from.x),Math.abs(p.y-from.y),1);for(let i=0;i<=n;i++){const cell=Math.round(from.y+(p.y-from.y)*i/n)*24+Math.round(from.x+(p.x-from.x)*i/n);paint.remove?paint.cells.delete(cell):paint.cells.add(cell);}paint.last=p;redraw();}
 editor.addEventListener('pointerdown',e=>{if(!$('edit').checked||!selected()?.mask)return;e.preventDefault();e.stopImmediatePropagation();const p=point(e);paint={id:e.pointerId,cells:new Set(selected().mask),last:p,remove:e.button===2||e.altKey};editor.setPointerCapture(e.pointerId);paintTo(p);},true);
 editor.addEventListener('pointermove',e=>{if(!paint||e.pointerId!==paint.id)return;e.preventDefault();e.stopImmediatePropagation();paintTo(point(e));},true);
 editor.addEventListener('pointerup',e=>{if(!paint||e.pointerId!==paint.id)return;e.preventDefault();e.stopImmediatePropagation();const cells=[...paint.cells].sort((a,b)=>a-b);paint=null;change(()=>{const p=getProject(),t=selected();if(p.frames.some(f=>t.frameIds.includes(f.id)&&f.locked))throw Error('Unlock the track source frames before changing its mask.');t.mask=cells;});},true);
 for(const event of ['pointercancel','lostpointercapture'])editor.addEventListener(event,()=>{paint=null;redraw();});
 return{panel,render,drawMask(ctx,cell){if(!$('edit').checked)return;ctx.fillStyle='#bd48e64d';for(const v of paint?.cells||selected()?.mask||[])ctx.fillRect(v%24*cell,Math.floor(v/24)*cell,cell,cell);},sample(frame,index,elapsed=performance.now()-started){if(!compiled)return frame;const result=sampleAnimationTracks(compiled,index,elapsed,{seed:Number($('seed').value)||0,muted:$('mute').checked?[selectedId]:[],solo:$('solo').checked?selectedId:null});return{...frame,rows:result.rows,gaze:result.gaze,origin:result.origin};}};
}
